const dadosLimpos = $('Code - Limpar Resposta Gemini').first().json;

return [
  {
    json: dadosLimpos.resposta_backend,
  },
];

const current = $input.first();

// O nome precisa ser igual ao nome do seu node Webhook.
// Se o seu Webhook tiver outro nome, troque aqui.
const webhook = $('Webhook Entrada').first();

const MODELO_GEMINI = 'gemini';

function removerMarkdown(texto) {
  return String(texto ?? '')
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();
}

function tentarParseJson(texto) {
  let limpo = removerMarkdown(texto);

  // Caso venha assim: text:{ ... }
  limpo = limpo.replace(/^text\s*:\s*/i, '').trim();

  // Primeira tentativa: parse direto
  try {
    return JSON.parse(limpo);
  } catch (error) {}

  // Segunda tentativa: pegar apenas o trecho entre { e }
  const inicio = limpo.indexOf('{');
  const fim = limpo.lastIndexOf('}');

  if (inicio !== -1 && fim !== -1 && fim > inicio) {
    const trechoJson = limpo.slice(inicio, fim + 1);

    try {
      return JSON.parse(trechoJson);
    } catch (error) {}

    // Terceira tentativa: caso existam \n literais no texto
    try {
      return JSON.parse(
        trechoJson
          .replace(/\\n/g, '\n')
          .replace(/\\t/g, '\t')
      );
    } catch (error) {}
  }

  throw new Error('A resposta do Gemini não contém JSON válido.');
}

function encontrarStringsComJson(valor, caminhos = [], caminhoAtual = '$', visitados = new WeakSet()) {
  if (valor === null || valor === undefined) {
    return caminhos;
  }

  if (typeof valor === 'string') {
    if (
      valor.includes('{') ||
      valor.includes('enunciado') ||
      valor.includes('resposta_aluno') ||
      valor.includes('confianca_extracao')
    ) {
      caminhos.push({
        caminho: caminhoAtual,
        valor,
      });
    }

    return caminhos;
  }

  if (typeof valor !== 'object') {
    return caminhos;
  }

  if (visitados.has(valor)) {
    return caminhos;
  }

  visitados.add(valor);

  if (Array.isArray(valor)) {
    valor.forEach((item, index) => {
      encontrarStringsComJson(item, caminhos, `${caminhoAtual}[${index}]`, visitados);
    });
  } else {
    for (const chave of Object.keys(valor)) {
      encontrarStringsComJson(valor[chave], caminhos, `${caminhoAtual}.${chave}`, visitados);
    }
  }

  return caminhos;
}

function extrairRespostaGemini(jsonGemini) {
  // Caso raro: o próprio JSON já seja a extração
  if (
    jsonGemini &&
    typeof jsonGemini === 'object' &&
    (
      jsonGemini.enunciado ||
      jsonGemini.desenvolvimento_aluno ||
      jsonGemini.resposta_aluno
    )
  ) {
    return jsonGemini;
  }

  // Caminhos comuns
  const candidatosDiretos = [
    jsonGemini.text,
    jsonGemini.output,
    jsonGemini.response,
    jsonGemini.content,
    jsonGemini.message?.content,
    jsonGemini.candidates?.[0]?.content?.parts?.[0]?.text,
    jsonGemini.content?.parts?.[0]?.text,
    jsonGemini.parts?.[0]?.text,
    jsonGemini.data?.text,
    jsonGemini.result?.text,
  ];

  for (const candidato of candidatosDiretos) {
    if (typeof candidato === 'string' && candidato.trim()) {
      try {
        return tentarParseJson(candidato);
      } catch (error) {}
    }

    if (
      candidato &&
      typeof candidato === 'object' &&
      (
        candidato.enunciado ||
        candidato.desenvolvimento_aluno ||
        candidato.resposta_aluno
      )
    ) {
      return candidato;
    }
  }

  // Busca profunda: procura qualquer string dentro da resposta que pareça conter JSON
  const stringsEncontradas = encontrarStringsComJson(jsonGemini);

  for (const item of stringsEncontradas) {
    try {
      return tentarParseJson(item.valor);
    } catch (error) {}
  }

  throw new Error('A resposta do Gemini não contém JSON válido.');
}

const webhookJson = webhook.json.body ?? webhook.json;

const submissionId =
  webhookJson.submission_id ??
  webhookJson.submissionId ??
  webhookJson.id ??
  null;

let parseOk = true;
let erroParse = null;
let extracao = {};
let debug = null;

try {
  extracao = extrairRespostaGemini(current.json);
} catch (error) {
  parseOk = false;
  erroParse = error.message;

  const stringsEncontradas = encontrarStringsComJson(current.json);

  debug = {
    chaves_disponiveis_no_gemini: Object.keys(current.json ?? {}),
    caminhos_com_texto_encontrados: stringsEncontradas.map(item => item.caminho),
    primeira_string_encontrada: stringsEncontradas[0]?.valor?.slice(0, 500) ?? null,
  };

  extracao = {};
}

const extracaoNormalizada = {
  enunciado: String(extracao.enunciado ?? ''),
  desenvolvimento_aluno: String(extracao.desenvolvimento_aluno ?? ''),
  resposta_aluno: String(extracao.resposta_aluno ?? ''),
  legibilidade: String(extracao.legibilidade ?? ''),
  confianca_extracao:
    extracao.confianca_extracao === undefined || extracao.confianca_extracao === null
      ? null
      : Number(extracao.confianca_extracao),
  observacoes: String(extracao.observacoes ?? ''),
};

const statusN8n = parseOk
  ? 'json_extraido_com_sucesso'
  : 'erro_parse_json';

const respostaBackend = {
  ok: parseOk,
  submission_id: submissionId,
  fluxo: 'extracao_imagem',
  status_n8n: statusN8n,
  provedor_ia: 'gemini',
  modelo: MODELO_GEMINI,
  extracao: extracaoNormalizada,
  erro_parse: erroParse,
};

return [
  {
    json: {
      timestamp: new Date().toISOString(),
      submission_id: submissionId,
      parse_ok: parseOk,
      status_n8n: statusN8n,
      provedor_ia: 'gemini',
      modelo: MODELO_GEMINI,
      enunciado: extracaoNormalizada.enunciado,
      desenvolvimento_aluno: extracaoNormalizada.desenvolvimento_aluno,
      resposta_aluno: extracaoNormalizada.resposta_aluno,
      legibilidade: extracaoNormalizada.legibilidade,
      confianca_extracao: extracaoNormalizada.confianca_extracao,
      observacoes: extracaoNormalizada.observacoes,
      erro_parse: erroParse,
      debug_parse: debug,
      resposta_backend: respostaBackend,
    },
  },
];

const webhook = $('Webhook Entrada').first();
const webhookJson = webhook.json.body ?? webhook.json;

const submissionId =
  webhookJson.submission_id ??
  webhookJson.submissionId ??
  webhookJson.id ??
  `sub_mock_${Date.now()}`;

return [
  {
    json: {
      ok: true,
      submission_id: submissionId,
      fluxo: "extracao_imagem",
      status_n8n: "mock_extracao_sem_gemini",
      provedor_ia: "mock",
      modelo: "sem_gemini",

      extracao: {
        enunciado: "02) Pedro tinha 4 moedas em sua carteira. Ele encontrou mais 5 moedas no chão enquanto caminhava pelo parque. Quantas moedas Pedro tem ao todo agora?",
        desenvolvimento_aluno: "4+5=9",
        resposta_aluno: "9",
        legibilidade: "alta",
        confianca_extracao: 1,
        observacoes: "Resposta fixa de teste gerada no n8n sem usar Gemini."
      },

      erro_parse: null
    }
  }
];
